    def get_config_section_key_dict_dict_list(self, section, key):
        return self.map_split_section_key(section, key, self.config[section][key])

    def map_split_section_key(self, section, key, value):
        return map(lambda x: map(lambda y: map(lambda z: z.split(","), y.split(",")), x.split(",")), value.split(","))


def _materialize(value):
    """Converts nested sequences  (including iterators) into lists."""
    if isinstance(value, str):
        return value
    try:
        items = iter(value)
    except TypeError:
        return value
    return [ _materialize(item) for item in items]


